export function fireEnemyWeapon(enemyObj, context, weaponOverride = null) {
  if (!enemyObj || !enemyObj.mesh) return false;
  if (enemyObj.mesh.userData && (enemyObj.mesh.userData.inPool || enemyObj.mesh.userData.isActive === false || enemyObj.mesh.userData.weaponsActive === false)) return false;

  const isContextObj = context && typeof context === 'object' && !context.isVector3;
  const scene = isContextObj ? context.scene : (typeof window !== 'undefined' ? window.scene : null);
  const camera = isContextObj ? context.camera : (typeof window !== 'undefined' ? window.camera : null);
  const state = isContextObj ? context.state : (typeof window !== 'undefined' ? window.state : null);
  const cameraRig = isContextObj ? context.cameraRig : null;
  const audioMgr = isContextObj ? context.audioMgr : null;
  const enemyBolts = isContextObj ? context.enemyBolts : (typeof weaponOverride === 'function' ? weaponOverride() : null);

  if (!scene || !camera || !enemyBolts) return false;
  if (enemyBolts.length > 80) return false;

  const playerPos = (isContextObj && context.playerPos)
    ? context.playerPos
    : (context && context.isVector3)
      ? context
      : ((state && state.isXR && cameraRig) ? cameraRig.position : (state ? state.position : camera.position));

  const w = (weaponOverride && typeof weaponOverride === 'object')
    ? weaponOverride
    : (enemyObj.weapons && enemyObj.weapons[0]) || (enemyObj.config && enemyObj.config.weapons && enemyObj.config.weapons[0]) || null;
  const cfg = enemyObj.config || enemyObj || {};
  const wName = (w && w.name) || cfg.weapon_name || 'Plasma Pulse';
  const rawWType = (w && w.type) ? w.type.toLowerCase() : '';
  const isMissile = rawWType === 'missile' || rawWType === 'torpedo' || /missile|strike|torpedo|rocket|warhead|ordnance|bomb/i.test(`${rawWType} ${wName} ${(w && w.id) || ''} ${(w && w.model_url) || ''}`);
  const wType = isMissile ? 'missile' : (rawWType || 'beam');
  const rawColor = (w && w.color) || enemyObj.weaponColor || cfg.weapon_color || '#c084fc';
  const boltColorHex = parseInt(String(rawColor).replace('#', '0x'), 16) || 0xff0055;
  const wDamage = (w && w.damage !== undefined) ? parseInt(w.damage) : (enemyObj.weaponDmg || cfg.weapon_damage || 6);
  const wSpeedRaw = (w && w.speed !== undefined) ? parseInt(w.speed) : (enemyObj.weaponSpeed || cfg.weapon_speed || 480);
  const boltSpeed = Math.max(45, Math.min(180, wSpeedRaw * (isMissile ? 0.16 : 0.24)));
  const wMount = (w && w.mount) || 'nose_cannon';

  const wScale = Number((w && w.scale) ?? cfg.weapon_scale ?? 1.0);
  const wScaleX = Number((w && w.scale_x) ?? cfg.weapon_scale_x ?? 1.0);
  const wScaleY = Number((w && w.scale_y) ?? cfg.weapon_scale_y ?? 1.0);
  const wScaleZ = Number((w && w.scale_z) ?? cfg.weapon_scale_z ?? 1.0);
  const wSizeX = Number((w && (w.size_x ?? (w.dimensions && w.dimensions.x))) ?? cfg.weapon_size_x ?? 1.0);
  const wSizeY = Number((w && (w.size_y ?? (w.dimensions && w.dimensions.y))) ?? cfg.weapon_size_y ?? 1.0);
  const wSizeZ = Number((w && (w.size_z ?? (w.dimensions && w.dimensions.z))) ?? cfg.weapon_size_z ?? 1.0);
  const wSpecialFx = (w && w.special_fx) || cfg.weapon_special_fx || 'cockpit_overlay_decals';
  const wSpecialFxFile = (w && w.special_fx_file) || cfg.weapon_special_fx_file || 'scene_images/screen_decals_spider_web_overlay_4.glb';
  const wSpecialFxType = (w && w.special_fx_type) || cfg.weapon_special_fx_type || 'overlay';
  const wId = (w && w.id) || (wName ? 'ew_' + wName.toLowerCase().replace(/[^a-z0-9]/g, '_') : 'ew_primary');

  const spawnOrigin = enemyObj.mesh.position.clone();
  if (wMount === 'dual_wingtip') {
    enemyObj._wingSide = (enemyObj._wingSide === 1) ? -1 : 1;
    spawnOrigin.x += enemyObj._wingSide * 1.3 * (enemyObj.baseScale || 1.0);
  } else if (wMount === 'turret_top') {
    spawnOrigin.y += 0.9 * (enemyObj.baseScale || 1.0);
  } else if (wMount === 'under_belly') {
    spawnOrigin.y -= 0.9 * (enemyObj.baseScale || 1.0);
  }

  const targetPoint = new THREE.Vector3(
    playerPos.x + (Math.random() - 0.5) * (isMissile ? 2.2 : 3.5),
    playerPos.y + (Math.random() - 0.5) * (isMissile ? 2.2 : 3.5),
    playerPos.z
  );
  const direction = new THREE.Vector3().subVectors(targetPoint, spawnOrigin).normalize();
  const boltQuat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, -1), direction);

  let mesh = null;
  let fromPool = false;

  if (typeof window !== 'undefined' && window.stageObjectPool && typeof window.stageObjectPool.spawnEnemyWeapon === 'function') {
    mesh = window.stageObjectPool.spawnEnemyWeapon(w || { id: wId, name: wName, type: wType, color: rawColor }, cfg, spawnOrigin, boltQuat, isMissile ? 'missile' : 'beam');
    if (mesh) fromPool = true;
  }

  if (!mesh) {
    const geom = new THREE.CylinderGeometry(0.14 * wSizeX, 0.22 * wSizeY, 5.5 * wSizeZ, 6);
    geom.rotateX(Math.PI / 2);
    const mat = new THREE.MeshBasicMaterial({ color: boltColorHex, transparent: true, opacity: 0.95 });
    mesh = new THREE.Mesh(geom, mat);
    mesh.scale.set(wScale * wScaleX, wScale * wScaleY, wScale * wScaleZ);
    mesh.position.copy(spawnOrigin);
    mesh.quaternion.copy(boltQuat);
    scene.add(mesh);
  } else {
    mesh.position.copy(spawnOrigin);
    mesh.quaternion.copy(boltQuat);
  }

  enemyBolts.push({
    mesh,
    fromPool,
    direction,
    speed: boltSpeed,
    damage: wDamage,
    weaponId: wId,
    weaponName: wName,
    weaponColor: rawColor,
    specialFx: wSpecialFx,
    specialFxFile: wSpecialFxFile,
    specialFxType: wSpecialFxType,
    scale: wScale,
    scale_x: wScaleX,
    scale_y: wScaleY,
    scale_z: wScaleZ,
    size_x: wSizeX,
    size_y: wSizeY,
    size_z: wSizeZ,
    dimensions: { x: wSizeX, y: wSizeY, z: wSizeZ },
    type: isMissile ? 'missile' : 'beam',
    spiralTime: Math.random() * Math.PI * 2,
    spawnTime: performance.now(),
    lifetime: isMissile ? 7.5 : 4.8
  });

  if (audioMgr && audioMgr.isInitialized && typeof audioMgr.playLaserBolt === 'function') {
    try { audioMgr.playLaserBolt(); } catch (e) {}
  }
  return true;
}

export function updateEnemyMovement(e, delta, context) {
  if (!e || !e.mesh || e.mesh.userData.inPool || e.mesh.userData.isActive === false || e.isActive === false || e.mesh.userData.movementActive === false) return false;
  const isContextObj = context && typeof context === 'object' && !context.isVector3;
  const now = (isContextObj && context.now) || performance.now();
  const playerPos = (isContextObj && context.playerPos)
    ? context.playerPos
    : (context && context.isVector3)
      ? context
      : { x: 0, y: 0, z: 220 };
  const laserBolts = (isContextObj && context.laserBolts) || [];
  const activeEnemies = (isContextObj && context.activeEnemies) || [];
  const enemyIndex = (isContextObj && context.enemyIndex !== undefined) ? context.enemyIndex : -1;
  const distToPlayer = e.mesh.position.distanceTo(playerPos);

  const dist10k = 10000 / 420;
  const dist5k = 5000 / 420;
  const targetZ10k = playerPos.z - dist10k;
  const targetZ5k = playerPos.z - dist5k;
  const spawnZ = (e.spawnPos && typeof e.spawnPos.z === 'number') ? e.spawnPos.z : -6.5;
  const baseScale = e.baseScale || 1.3;
  const basePitchDown = 0.22;

  if (!e.maneuverState) {
    e.maneuverState = (e.phase === 'RUSH_OUT') ? 'RUSH_OUT' : 'CRUISE_10K';
    e.levelPitchProgress = 0.0;
    e.isLevel = false;
    e.hasFiredThisLevel = false;
    e.nextLevelTime = now + 1500 + Math.random() * 3500;
  }

  if (e.phase === 'RUSH_OUT' || e.maneuverState === 'RUSH_OUT') {
    e.mesh.position.z += (e.speed || 45) * delta;
    e.mesh.position.x += (playerPos.x + (e.targetScatterX || 0) * 0.25 - e.mesh.position.x) * delta * 0.55;
    e.mesh.position.y += (playerPos.y + (e.targetScatterY || 0) * 0.25 - e.mesh.position.y) * delta * 0.55;

    const totalDist = Math.max(10, targetZ10k - spawnZ);
    const distTraveled = e.mesh.position.z - spawnZ;
    const rushProgress = THREE.MathUtils.clamp(distTraveled / totalDist, 0.0, 1.0);
    const curScale = THREE.MathUtils.lerp(0.12, baseScale, rushProgress);
    e.mesh.scale.set(curScale, curScale, curScale);

    const rushDx = playerPos.x - e.mesh.position.x;
    const rushDy = playerPos.y - e.mesh.position.y;
    const rushDz = Math.max(5.0, playerPos.z - e.mesh.position.z);
    const rushLookYaw = THREE.MathUtils.clamp(Math.atan2(rushDx, rushDz), -0.35, 0.35);
    const rushLookPitch = THREE.MathUtils.clamp(-Math.atan2(rushDy, rushDz), -0.20, 0.20);
    e.levelPitchProgress = 0.0;
    e.isLevel = false;
    e.mesh.rotation.set(basePitchDown + rushLookPitch, rushLookYaw, 0, 'YXZ');

    if (e.mesh.position.z >= targetZ10k || distToPlayer <= dist10k) {
      e.mesh.position.z = targetZ10k;
      e.phase = 'SCATTER_AND_EVADE';
      e.maneuverState = 'CRUISE_10K';
      e.stoppedTime = now;
      e.nextLevelTime = now + 1500 + Math.random() * 3500;
    }
    return true;
  }

  const grid = (isContextObj && context.snapGrid) || (typeof window !== 'undefined' && window.snapGrid);
  const cols = (grid && grid.cols) ? grid.cols : 15;
  const rows = (grid && grid.rows) ? grid.rows : 7;
  const cellW = 48.8 / cols;
  const cellH = 27.5 / rows;

  if (now > (e.scatterRetargetTime || 0)) {
    e.scatterRetargetTime = now + 4000 + Math.random() * 4000;
    const maxCol = Math.max(2, Math.floor(cols / 2) - 1);
    const maxRow = Math.max(1, Math.floor(rows / 2) - 1);
    const signX = Math.random() > 0.5 ? 1 : -1;
    const colSlot = signX * (1 + Math.floor(Math.random() * maxCol));
    const rowSlot = Math.floor((Math.random() * 2 - 1) * maxRow);
    e.targetScatterX = colSlot * cellW;
    e.targetScatterY = rowSlot * cellH;
  }

  const screenTargetX = playerPos.x + (e.targetScatterX || 0);
  const screenTargetY = playerPos.y + (e.targetScatterY || 0);
  e.mesh.position.x += (screenTargetX - e.mesh.position.x) * delta * 2.2;
  e.mesh.position.y += (screenTargetY - e.mesh.position.y) * delta * 2.2;

  const t = (now - (e.stoppedTime || now)) * 0.001;
  const evaVx = Math.sin(t * (e.evaFreqX || 1.8) + (e.evaPhaseX || 0)) * (e.evaAmpX || 3.0);
  const evaVy = Math.cos(t * (e.evaFreqY || 1.6) + (e.evaPhaseY || 0)) * (e.evaAmpY || 2.4);
  const evaVz = Math.sin(t * (e.evaFreqZ || 1.2) + (e.evaPhaseZ || 0)) * (e.evaAmpZ || 1.6);
  e.mesh.position.x += evaVx * delta;
  e.mesh.position.y += evaVy * delta;
  e.mesh.position.z += evaVz * delta;

  if (now >= (e.nextJukeTime || 0)) {
    e.nextJukeTime = now + 1400 + Math.random() * 2000;
    e.jukeEndTime = now + 350 + Math.random() * 350;
    if (e.jukeVelocity && typeof e.jukeVelocity.set === 'function') {
      e.jukeVelocity.set(
        (Math.random() - 0.5) * 30,
        (Math.random() - 0.5) * 22,
        (Math.random() - 0.5) * 6
      );
    }
  }
  if (e.jukeVelocity) {
    if (now < e.jukeEndTime) {
      e.mesh.position.addScaledVector(e.jukeVelocity, delta);
    } else {
      e.jukeVelocity.multiplyScalar(Math.max(0, 1.0 - delta * 4.5));
    }
  }

  for (let li = 0; li < laserBolts.length; li++) {
    const lbolt = laserBolts[li];
    if (!lbolt || !lbolt.mesh) continue;
    const ldist = lbolt.mesh.position.distanceTo(e.mesh.position);
    if (ldist < 7.2) {
      const dodgeDir = new THREE.Vector3().subVectors(e.mesh.position, lbolt.mesh.position);
      dodgeDir.z = 0;
      if (dodgeDir.lengthSq() > 0.001) {
        dodgeDir.normalize();
        e.mesh.position.addScaledVector(dodgeDir, 20.0 * delta);
      }
      break;
    }
  }

  switch (e.maneuverState) {
    case 'CRUISE_10K': {
      e.mesh.position.z += (targetZ10k - e.mesh.position.z) * delta * 3.2;
      e.levelPitchProgress = Math.max(0.0, (e.levelPitchProgress || 0) - delta * 3.0);
      e.isLevel = false;
      e.mesh.scale.set(baseScale, baseScale, baseScale);
      if (now >= (e.nextLevelTime || 0)) {
        e.maneuverState = 'LEVELING_OFF';
        e.hasFiredThisLevel = false;
      }
      break;
    }
    case 'LEVELING_OFF': {
      e.mesh.position.z += (targetZ10k - e.mesh.position.z) * delta * 3.2;
      e.levelPitchProgress = Math.min(1.0, (e.levelPitchProgress || 0) + delta * 2.8);
      e.mesh.scale.set(baseScale, baseScale, baseScale);
      if (e.levelPitchProgress >= 0.96) {
        e.levelPitchProgress = 1.0;
        e.isLevel = true;
        e.maneuverState = 'LEVEL_FIRING';
        e.levelFireEndTime = now + 600;
        if (!e.hasFiredThisLevel) {
          e.hasFiredThisLevel = true;
          fireEnemyWeapon(e, context);
        }
      }
      break;
    }
    case 'LEVEL_FIRING': {
      e.mesh.position.z += (targetZ10k - e.mesh.position.z) * delta * 3.2;
      e.levelPitchProgress = 1.0;
      e.isLevel = true;
      e.mesh.scale.set(baseScale, baseScale, baseScale);
      if (now >= (e.levelFireEndTime || 0)) {
        e.isLevel = false;
        e.maneuverState = 'TILTING_FORWARD';
      }
      break;
    }
    case 'TILTING_FORWARD': {
      e.mesh.position.z += (targetZ10k - e.mesh.position.z) * delta * 3.2;
      e.levelPitchProgress = Math.max(0.0, (e.levelPitchProgress || 1.0) - delta * 2.8);
      e.isLevel = false;
      e.mesh.scale.set(baseScale, baseScale, baseScale);
      if (e.levelPitchProgress <= 0.04) {
        e.levelPitchProgress = 0.0;
        e.maneuverState = 'ADVANCE_5K';
      }
      break;
    }
    case 'ADVANCE_5K': {
      e.levelPitchProgress = 0.0;
      e.isLevel = false;
      e.mesh.position.z += (targetZ5k - e.mesh.position.z) * delta * 3.5;
      const advanceProgress = THREE.MathUtils.clamp((e.mesh.position.z - targetZ10k) / (targetZ5k - targetZ10k), 0.0, 1.0);
      const curScale = baseScale * (1.0 + 0.02 * advanceProgress);
      e.mesh.scale.set(curScale, curScale, curScale);
      if (advanceProgress >= 0.98 || Math.abs(targetZ5k - e.mesh.position.z) < 0.2) {
        e.mesh.position.z = targetZ5k;
        e.maneuverState = 'LEVELING_OFF_5K';
        e.hasFiredThisLevel = false;
      }
      break;
    }
    case 'LEVELING_OFF_5K': {
      e.mesh.position.z += (targetZ5k - e.mesh.position.z) * delta * 3.5;
      e.levelPitchProgress = Math.min(1.0, (e.levelPitchProgress || 0) + delta * 3.0);
      const curScale = baseScale * 1.02;
      e.mesh.scale.set(curScale, curScale, curScale);
      if (e.levelPitchProgress >= 0.96) {
        e.levelPitchProgress = 1.0;
        e.isLevel = true;
        e.maneuverState = 'LEVEL_FIRING_5K';
        e.hold5kEndTime = now + 2400;
        if (!e.hasFiredThisLevel) {
          e.hasFiredThisLevel = true;
          fireEnemyWeapon(e, context);
        }
      }
      break;
    }
    case 'LEVEL_FIRING_5K':
    case 'HOLD_5K': {
      e.levelPitchProgress = 1.0;
      e.isLevel = true;
      e.mesh.position.z += (targetZ5k - e.mesh.position.z) * delta * 3.5;
      const curScale = baseScale * 1.02;
      e.mesh.scale.set(curScale, curScale, curScale);
      if (now >= (e.hold5kEndTime || 0)) {
        e.isLevel = false;
        e.maneuverState = 'TILTING_FORWARD_5K';
      }
      break;
    }
    case 'TILTING_FORWARD_5K': {
      e.mesh.position.z += (targetZ5k - e.mesh.position.z) * delta * 3.5;
      e.levelPitchProgress = Math.max(0.0, (e.levelPitchProgress || 1.0) - delta * 3.0);
      e.isLevel = false;
      const curScale = baseScale * 1.02;
      e.mesh.scale.set(curScale, curScale, curScale);
      if (e.levelPitchProgress <= 0.04) {
        e.levelPitchProgress = 0.0;
        e.maneuverState = 'RETREAT_10K';
      }
      break;
    }
    case 'RETREAT_10K': {
      e.levelPitchProgress = 0.0;
      e.isLevel = false;
      e.mesh.position.z += (targetZ10k - e.mesh.position.z) * delta * 2.8;
      const retreatProgress = THREE.MathUtils.clamp((targetZ5k - e.mesh.position.z) / (targetZ5k - targetZ10k), 0.0, 1.0);
      const curScale = baseScale * (1.02 - 0.02 * retreatProgress);
      e.mesh.scale.set(curScale, curScale, curScale);
      if (retreatProgress >= 0.98 || Math.abs(targetZ10k - e.mesh.position.z) < 0.2) {
        e.mesh.position.z = targetZ10k;
        e.mesh.scale.set(baseScale, baseScale, baseScale);
        e.maneuverState = 'CRUISE_10K';
        e.nextLevelTime = now + 2500 + Math.random() * 4500;
      }
      break;
    }
    default: {
      e.maneuverState = 'CRUISE_10K';
      break;
    }
  }

  const dx = playerPos.x - e.mesh.position.x;
  const dy = playerPos.y - e.mesh.position.y;
  const dz = Math.max(5.0, playerPos.z - e.mesh.position.z);
  const rawLookYaw = Math.atan2(dx, dz);
  const rawLookPitch = -Math.atan2(dy, dz);
  const gridYawStep = cellW / dist10k;
  const gridPitchStep = cellH / dist10k;
  const snappedYaw = Math.round(rawLookYaw / gridYawStep) * gridYawStep;
  const snappedPitch = Math.round(rawLookPitch / gridPitchStep) * gridPitchStep;
  const lookYaw = THREE.MathUtils.clamp(THREE.MathUtils.lerp(rawLookYaw, snappedYaw, 0.45), -0.45, 0.45);
  const lookPitch = THREE.MathUtils.clamp(THREE.MathUtils.lerp(rawLookPitch, snappedPitch, 0.45), -0.28, 0.28);

  const jukeVx = e.jukeVelocity ? e.jukeVelocity.x : 0;
  const jukeVy = e.jukeVelocity ? e.jukeVelocity.y : 0;
  const netVx = (screenTargetX - e.mesh.position.x) * 1.1 + jukeVx + evaVx;
  const netVy = (screenTargetY - e.mesh.position.y) * 1.1 + jukeVy + evaVy;
  const roll = -THREE.MathUtils.clamp(netVx * 0.045, -0.65, 0.65);
  const yaw = lookYaw + THREE.MathUtils.clamp(-netVx * 0.02, -0.22, 0.22);
  const effectiveBasePitch = basePitchDown * (1.0 - (e.levelPitchProgress || 0));
  const pitch = effectiveBasePitch + lookPitch + THREE.MathUtils.clamp(netVy * 0.035, -0.18, 0.18);
  e.mesh.rotation.set(pitch, yaw, roll, 'YXZ');

  if (e.mesh.userData && e.mesh.userData.spinRing) {
    e.mesh.userData.spinRing.rotation.z += 6.0 * delta;
  }

  for (let j = 0; j < activeEnemies.length; j++) {
    if (j === enemyIndex) continue;
    const other = activeEnemies[j];
    if (!other || !other.mesh) continue;
    const sepVec = new THREE.Vector3().subVectors(e.mesh.position, other.mesh.position);
    const sepDist = sepVec.length();
    const otherScale = (other.mesh.scale && typeof other.mesh.scale.x === 'number') ? other.mesh.scale.x : 1.0;
    const curScaleX = (e.mesh.scale && typeof e.mesh.scale.x === 'number') ? e.mesh.scale.x : 1.0;
    const minSafeSep = Math.max(5.5, (curScaleX + otherScale) * 2.8);
    if (sepDist < minSafeSep && sepDist > 0.001) {
      const overlapFactor = (minSafeSep - sepDist) / minSafeSep;
      const repulse = sepVec.normalize().multiplyScalar(overlapFactor * 20.0 * delta);
      e.mesh.position.add(repulse);
    }
  }

  return true;
}

export function pullEnemyWave(waveNumber = 1, engineApi = null, context = {}) {
  const api = engineApi || (context && context.engineApi);
  if (!api || typeof api.spawnEnemyWaveFromPool !== 'function') return [];

  const waves = stageConfig.waves || [
    { wave_number: 1, enemy_count: 5, interval_seconds: 0 },
    { wave_number: 2, enemy_count: 10, interval_seconds: 15 }
  ];
  const waveCfg = waves.find(w => w.wave_number === waveNumber) || waves[waveNumber - 1] || {
    wave_number: waveNumber,
    enemy_count: waveNumber === 1 ? 5 : 10,
    interval_seconds: waveNumber === 1 ? 0 : 15
  };

  return api.spawnEnemyWaveFromPool(waveCfg.enemy_count, waveCfg, stageConfig.enemies);
}

export function updateStageWaves(engineApi, context = {}) {
  const api = engineApi || (context && context.engineApi);
  if (!api || !api.state) return;
  const st = api.state;
  if (!st.hasStarted || st.isPaused || st.isGameOver || st.isHyperWarping) return;

  const now = context.now || performance.now();
  const activeEnemies = context.activeEnemies || (typeof api.getActiveEnemies === 'function' ? api.getActiveEnemies() : []);
  const totalWaves = stageConfig.total_waves || 2;
  const waveIntervalMs = (stageConfig.wave_interval_seconds || 15) * 1000;

  if (st.currentWave === 0) {
    pullEnemyWave(1, api, context);
  } else if (st.currentWave === 1 && totalWaves >= 2) {
    const waveElapsed = now - (st.waveStartTime || 0);
    const wave1Remaining = activeEnemies.filter(e => e && e.isActive && e.waveNumber === 1).length;
    if (waveElapsed >= waveIntervalMs || (wave1Remaining === 0 && waveElapsed >= 4500)) {
      pullEnemyWave(2, api, context);
    }
  }
}

// =========================================================================
// COCKPIT OVERLAY & IMPACT DECALS MANAGEMENT
// =========================================================================

let activeCockpitCracksMesh = null;
let activeCockpitCracksPool = null;

function getActiveOverlay() {
  if (typeof window !== 'undefined' && window.cockpitOverlayCamera) {
    const onOvCam = window.cockpitOverlayCamera.getObjectByName('cockpit_overlay_object') || window.cockpitOverlayCamera.getObjectByName('cockpit_cracks_overlay');
    if (onOvCam) return onOvCam;
  }
  const cam = (typeof window !== 'undefined' && window.camera) ? window.camera : null;
  if (cam) {
    const onCam = cam.getObjectByName('cockpit_overlay_object') || cam.getObjectByName('cockpit_cracks_overlay');
    if (onCam) return onCam;
  }
  if (activeCockpitCracksMesh) return activeCockpitCracksMesh;
  if (activeCockpitCracksPool && activeCockpitCracksPool.cockpitCracksMesh) {
    return activeCockpitCracksPool.cockpitCracksMesh;
  }
  return null;
}

function getOverlayHostCamera(fallbackCamera = null) {
  if (typeof window !== 'undefined') {
    if (typeof window.getCockpitOverlayHostCamera === 'function') {
      return window.getCockpitOverlayHostCamera(fallbackCamera);
    }
    const inXrPresenting = !!(window.renderer && window.renderer.xr && window.renderer.xr.isPresenting);
    if (!inXrPresenting && window.cockpitOverlayCamera && window.cockpitOverlayRenderer) {
      return window.cockpitOverlayCamera;
    }
    return fallbackCamera || window.camera || null;
  }
  return fallbackCamera;
}

function createDefaultDecalThresholdState(shieldPct = 100, healthPct = 100) {
  const s = Math.max(0, Math.min(100, Number.isFinite(shieldPct) ? shieldPct : 100));
  const h = Math.max(0, Math.min(100, Number.isFinite(healthPct) ? healthPct : 100));
  return {
    anchorShieldPct: s,
    anchorHealthPct: h,
    lastObservedShieldPct: s,
    lastObservedHealthPct: h
  };
}

function getDecalThresholdTracker(overlay = null) {
  const target = overlay || getActiveOverlay();
  const win = (typeof window !== 'undefined') ? window : null;
  if (target) {
    if (!target._cockpitDecalThreshold) {
      target._cockpitDecalThreshold = (win && win.__cockpitDecalThreshold)
        ? win.__cockpitDecalThreshold
        : createDefaultDecalThresholdState(100, 100);
    }
    if (win) {
      win.__cockpitDecalThreshold = target._cockpitDecalThreshold;
    }
    return target._cockpitDecalThreshold;
  }
  if (win) {
    if (!win.__cockpitDecalThreshold) {
      win.__cockpitDecalThreshold = createDefaultDecalThresholdState(100, 100);
    }
    return win.__cockpitDecalThreshold;
  }
  return createDefaultDecalThresholdState(100, 100);
}

export function getAvailableCockpitDecalCount(overlay = null) {
  const target = overlay || getActiveOverlay();
  if (!target) return 18;
  let decals = target._cockpitDecals || (target.userData && target.userData.decals) || null;
  if (!decals && typeof setupCockpitCracksHierarchy === 'function') {
    setupCockpitCracksHierarchy(target, false);
    decals = target._cockpitDecals || (target.userData && target.userData.decals) || null;
  }
  if (!decals) return 18;
  const count =
    (Array.isArray(decals.laserBurns) ? decals.laserBurns.length : 0) +
    (Array.isArray(decals.missileStrikes) ? decals.missileStrikes.length : 0) +
    (decals.brokenCore ? 1 : 0) +
    (decals.brokenScreen ? 1 : 0);
  return count > 0 ? count : 18;
}

export function resetCockpitDecalThreshold(overlay = null) {
  const fresh = createDefaultDecalThresholdState(100, 100);
  const target = overlay || getActiveOverlay();
  if (target) {
    target._cockpitDecalThreshold = fresh;
  }
  if (typeof window !== 'undefined') {
    window.__cockpitDecalThreshold = fresh;
  }
  return fresh;
}

export function syncCockpitDecalThreshold(overlay = null, shieldPct = null, healthPct = null) {
  const EPS = 1e-6;
  const target = overlay || getActiveOverlay();
  const tracker = getDecalThresholdTracker(target);
  const st = (typeof window !== 'undefined' && window.state) ? window.state : null;
  const maxS = (st && st.maxShield > 0) ? st.maxShield : 100;
  const maxH = (st && st.maxHealth > 0) ? st.maxHealth : 100;

  if (typeof shieldPct === 'number' && Number.isFinite(shieldPct)) {
    const sPct = Math.max(0, Math.min(100, shieldPct));
    if (sPct > tracker.lastObservedShieldPct + EPS || sPct >= 100 - EPS) {
      tracker.anchorShieldPct = sPct;
    }
    tracker.lastObservedShieldPct = sPct;
  } else if (st && typeof st.playerShield === 'number') {
    const sPct = Math.max(0, Math.min(100, (st.playerShield / maxS) * 100));
    if (sPct > tracker.lastObservedShieldPct + EPS || sPct >= 100 - EPS) {
      tracker.anchorShieldPct = sPct;
    }
    tracker.lastObservedShieldPct = sPct;
  }

  if (typeof healthPct === 'number' && Number.isFinite(healthPct)) {
    const hPct = Math.max(0, Math.min(100, healthPct));
    if (hPct > tracker.lastObservedHealthPct + EPS || hPct >= 100 - EPS) {
      tracker.anchorHealthPct = hPct;
    }
    tracker.lastObservedHealthPct = hPct;
  } else if (st && typeof st.playerHealth === 'number') {
    const hPct = Math.max(0, Math.min(100, (st.playerHealth / maxH) * 100));
    if (hPct > tracker.lastObservedHealthPct + EPS || hPct >= 100 - EPS) {
      tracker.anchorHealthPct = hPct;
    }
    tracker.lastObservedHealthPct = hPct;
  }

  return tracker;
}

export function evaluateWeaponDecalThreshold(overlay = null, damageContext = null) {
  const EPS = 1e-6;
  const target = overlay || getActiveOverlay();
  const tracker = getDecalThresholdTracker(target);
  const availableDecals = getAvailableCockpitDecalCount(target);
  const stepPct = 100 / Math.max(1, availableDecals);

  const ctx = (damageContext && typeof damageContext === 'object') ? damageContext : {};
  const st = (typeof window !== 'undefined' && window.state) ? window.state : null;
  const maxShield = (typeof ctx.maxShield === 'number' && ctx.maxShield > 0)
    ? ctx.maxShield
    : ((st && st.maxShield > 0) ? st.maxShield : 100);
  const maxHealth = (typeof ctx.maxHealth === 'number' && ctx.maxHealth > 0)
    ? ctx.maxHealth
    : ((st && st.maxHealth > 0) ? st.maxHealth : 100);

  const rawShieldAfter = (typeof ctx.shieldAfter === 'number' && Number.isFinite(ctx.shieldAfter))
    ? (ctx.shieldAfter / maxShield) * 100
    : ((st && typeof st.playerShield === 'number') ? (st.playerShield / maxShield) * 100 : tracker.lastObservedShieldPct);
  const rawHealthAfter = (typeof ctx.healthAfter === 'number' && Number.isFinite(ctx.healthAfter))
    ? (ctx.healthAfter / maxHealth) * 100
    : ((st && typeof st.playerHealth === 'number') ? (st.playerHealth / maxHealth) * 100 : tracker.lastObservedHealthPct);

  const shieldAfterPct = Math.max(0, Math.min(100, rawShieldAfter));
  const healthAfterPct = Math.max(0, Math.min(100, rawHealthAfter));

  const shieldBeforePct = (typeof ctx.shieldBefore === 'number' && Number.isFinite(ctx.shieldBefore))
    ? Math.max(0, Math.min(100, (ctx.shieldBefore / maxShield) * 100))
    : tracker.lastObservedShieldPct;
  const healthBeforePct = (typeof ctx.healthBefore === 'number' && Number.isFinite(ctx.healthBefore))
    ? Math.max(0, Math.min(100, (ctx.healthBefore / maxHealth) * 100))
    : tracker.lastObservedHealthPct;

  if (shieldBeforePct > tracker.lastObservedShieldPct + EPS) {
    tracker.anchorShieldPct = shieldBeforePct;
  }
  if (healthBeforePct > tracker.lastObservedHealthPct + EPS) {
    tracker.anchorHealthPct = healthBeforePct;
  }
  if (shieldAfterPct > tracker.lastObservedShieldPct + EPS) {
    tracker.anchorShieldPct = shieldAfterPct;
  }
  if (healthAfterPct > tracker.lastObservedHealthPct + EPS) {
    tracker.anchorHealthPct = healthAfterPct;
  }

  const shieldReduced = shieldAfterPct < shieldBeforePct - EPS;
  const healthReduced = healthAfterPct < healthBeforePct - EPS;

  let shouldTrigger = false;
  if (shieldReduced) {
    const shieldDrop = tracker.anchorShieldPct - shieldAfterPct;
    if (shieldDrop >= stepPct - EPS) {
      const stepsCrossed = Math.floor((shieldDrop + EPS) / stepPct);
      tracker.anchorShieldPct = Math.max(0, tracker.anchorShieldPct - stepsCrossed * stepPct);
      shouldTrigger = true;
    }
  }
  if (healthReduced) {
    const healthDrop = tracker.anchorHealthPct - healthAfterPct;
    if (healthDrop >= stepPct - EPS) {
      const stepsCrossed = Math.floor((healthDrop + EPS) / stepPct);
      tracker.anchorHealthPct = Math.max(0, tracker.anchorHealthPct - stepsCrossed * stepPct);
      shouldTrigger = true;
    }
  }

  tracker.lastObservedShieldPct = shieldAfterPct;
  tracker.lastObservedHealthPct = healthAfterPct;

  return {
    shouldTrigger,
    availableDecals,
    stepPct,
    shieldAfterPct,
    healthAfterPct,
    anchorShieldPct: tracker.anchorShieldPct,
    anchorHealthPct: tracker.anchorHealthPct
  };
}

export async function setupCockpitCracksOverlay(camera, pool = null, scene = null) {
  const fovCam = camera || (typeof window !== 'undefined' ? window.camera : null);
  const hostCam = getOverlayHostCamera(fovCam);
  if (!pool && typeof window !== 'undefined' && window.stageObjectPool) {
    pool = window.stageObjectPool;
  }

  if (pool) {
    activeCockpitCracksPool = pool;
    if (pool.cockpitOverlayReadyPromise) {
      try { await pool.cockpitOverlayReadyPromise; } catch (_) {}
    }
    if (typeof pool.getCockpitCracksOverlay === 'function') {
      activeCockpitCracksMesh = pool.getCockpitCracksOverlay(fovCam);
      if (activeCockpitCracksMesh) {
        if (hostCam) {
          const otherCam = (typeof window !== 'undefined')
            ? ((hostCam === window.cockpitOverlayCamera) ? fovCam : window.cockpitOverlayCamera)
            : null;
          if (otherCam) {
            const stray = otherCam.getObjectByName('cockpit_overlay_object') || otherCam.getObjectByName('cockpit_cracks_overlay');
            if (stray && stray !== activeCockpitCracksMesh) otherCam.remove(stray);
          }
          if (activeCockpitCracksMesh.parent && activeCockpitCracksMesh.parent !== hostCam) {
            activeCockpitCracksMesh.parent.remove(activeCockpitCracksMesh);
          }
          if (activeCockpitCracksMesh.parent !== hostCam) {
            hostCam.add(activeCockpitCracksMesh);
          }
        }
        fitCockpitCracksToCamera(activeCockpitCracksMesh, fovCam || hostCam);
        return activeCockpitCracksMesh;
      }
    }
  }

  const existing = getActiveOverlay();
  if (existing) {
    activeCockpitCracksMesh = existing;
    if (hostCam) {
      if (existing.parent && existing.parent !== hostCam) {
        existing.parent.remove(existing);
      }
      if (existing.parent !== hostCam) {
        hostCam.add(existing);
      }
    }
    fitCockpitCracksToCamera(activeCockpitCracksMesh, fovCam || hostCam);
    return activeCockpitCracksMesh;
  }

  return activeCockpitCracksMesh;
}

function computeOverlayLocalBounds(mesh) {
  if (!mesh) return null;
  if (mesh.userData && mesh.userData._overlayLocalBounds) {
    return mesh.userData._overlayLocalBounds;
  }

  const savedPos = mesh.position.clone();
  const savedQuat = mesh.quaternion.clone();
  const savedScale = mesh.scale.clone();

  mesh.position.set(0, 0, 0);
  mesh.quaternion.identity();
  mesh.scale.set(1, 1, 1);
  mesh.updateMatrixWorld(true);

  const invRoot = new THREE.Matrix4().copy(mesh.matrixWorld).invert();
  const localMat = new THREE.Matrix4();
  const tmpVec = new THREE.Vector3();

  const glassMeshes = [];
  const screenWebMeshes = [];
  const allMeshes = [];
  mesh.traverse((child) => {
    if (!child.isMesh || !child.geometry || !child.geometry.attributes || !child.geometry.attributes.position) return;
    const lname = (child.name || '').toLowerCase();
    if (lname.includes('solid_back') || lname.includes('solid_front') || lname.includes('solid_panel')) return;
    allMeshes.push(child);
    if (lname.includes('translucent') || lname.includes('clear_screen')) {
      glassMeshes.push(child);
    } else if (lname.includes('brokenspiderweb_screen') || (lname.includes('spiderweb') && lname.includes('screen'))) {
      screenWebMeshes.push(child);
    }
  });

  const targetMeshes = glassMeshes.length > 0 ? glassMeshes : (screenWebMeshes.length > 0 ? screenWebMeshes : allMeshes);

  let minX = Infinity, maxX = -Infinity;
  let minY = Infinity, maxY = -Infinity;
  let minZ = Infinity, maxZ = -Infinity;

  for (const child of targetMeshes) {
    localMat.multiplyMatrices(invRoot, child.matrixWorld);
    const pos = child.geometry.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      tmpVec.fromBufferAttribute(pos, i).applyMatrix4(localMat);
      if (tmpVec.x < minX) minX = tmpVec.x;
      if (tmpVec.x > maxX) maxX = tmpVec.x;
      if (tmpVec.y < minY) minY = tmpVec.y;
      if (tmpVec.y > maxY) maxY = tmpVec.y;
      if (tmpVec.z < minZ) minZ = tmpVec.z;
      if (tmpVec.z > maxZ) maxZ = tmpVec.z;
    }
  }

  mesh.position.copy(savedPos);
  mesh.quaternion.copy(savedQuat);
  mesh.scale.copy(savedScale);
  mesh.updateMatrixWorld(true);

  let bounds;
  if (!Number.isFinite(minX) || (maxX - minX) < 0.001 || (maxY - minY) < 0.001) {
    bounds = {
      halfW: 0.80,
      halfH: 0.45,
      centerX: 0.0,
      centerY: 0.0,
      minZ: -2.0,
      maxZ: -1.6984,
      minEdgeZX: -1.7776,
      minEdgeZY: -1.9332,
      isPreOffset: true
    };
  } else {
    const halfW = (maxX - minX) * 0.5;
    const halfH = (maxY - minY) * 0.5;
    const centerX = (minX + maxX) * 0.5;
    const centerY = (minY + maxY) * 0.5;
    let minEdgeZX = Infinity;
    let minEdgeZY = Infinity;

    mesh.position.set(0, 0, 0);
    mesh.quaternion.identity();
    mesh.scale.set(1, 1, 1);
    mesh.updateMatrixWorld(true);
    for (const child of targetMeshes) {
      localMat.multiplyMatrices(invRoot, child.matrixWorld);
      const pos = child.geometry.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        tmpVec.fromBufferAttribute(pos, i).applyMatrix4(localMat);
        if (Math.abs(tmpVec.x - centerX) >= halfW * 0.97 && tmpVec.z < minEdgeZX) {
          minEdgeZX = tmpVec.z;
        }
        if (Math.abs(tmpVec.y - centerY) >= halfH * 0.97 && tmpVec.z < minEdgeZY) {
          minEdgeZY = tmpVec.z;
        }
      }
    }
    mesh.position.copy(savedPos);
    mesh.quaternion.copy(savedQuat);
    mesh.scale.copy(savedScale);
    mesh.updateMatrixWorld(true);

    bounds = {
      halfW,
      halfH,
      centerX,
      centerY,
      minZ,
      maxZ,
      minEdgeZX: Number.isFinite(minEdgeZX) ? minEdgeZX : minZ,
      minEdgeZY: Number.isFinite(minEdgeZY) ? minEdgeZY : minZ,
      isPreOffset: maxZ < -0.2
    };
  }

  mesh.userData = mesh.userData || {};
  mesh.userData._overlayLocalBounds = bounds;
  return bounds;
}

export function fitCockpitCracksToCamera(mesh, camera) {
  if (!mesh) return;
  const fovCam = camera || (typeof window !== 'undefined' ? window.camera : null);
  if (!fovCam) return;

  const aspect = (fovCam.aspect && fovCam.aspect > 0)
    ? fovCam.aspect
    : (typeof window !== 'undefined' && window.innerHeight > 0 ? window.innerWidth / window.innerHeight : 16 / 9);
  const pm = (fovCam.projectionMatrix && fovCam.projectionMatrix.elements) ? fovCam.projectionMatrix.elements : null;
  const isXrPresenting = !!(typeof window !== 'undefined' && window.renderer && window.renderer.xr && window.renderer.xr.isPresenting);

  let tanHalfV = 0;
  let tanHalfH = 0;
  let asymX = 0;
  let asymY = 0;

  if (isXrPresenting && pm && pm[5] > 0 && pm[0] > 0) {
    tanHalfV = 1.0 / pm[5];
    tanHalfH = 1.0 / pm[0];
    asymX = Math.abs(pm[8] || 0);
    asymY = Math.abs(pm[9] || 0);
  } else if (fovCam.fov && fovCam.fov > 0) {
    const vFovRad = (fovCam.fov * Math.PI) / 180;
    tanHalfV = Math.tan(vFovRad / 2);
    tanHalfH = tanHalfV * aspect;
  } else if (pm && pm[5] > 0) {
    tanHalfV = 1.0 / pm[5];
    tanHalfH = (pm[0] > 0) ? (1.0 / pm[0]) : (tanHalfV * aspect);
    asymX = Math.abs(pm[8] || 0);
    asymY = Math.abs(pm[9] || 0);
  } else {
    const vFovRad = (65 * Math.PI) / 180;
    tanHalfV = Math.tan(vFovRad / 2);
    tanHalfH = tanHalfV * aspect;
  }

  const reqHalfSlopeX = tanHalfH * (1.0 + asymX);
  const reqHalfSlopeY = tanHalfV * (1.0 + asymY);

  if (!isXrPresenting && typeof window !== 'undefined' && window.cockpitOverlayCamera) {
    const ovCam = window.cockpitOverlayCamera;
    const targetFov = (fovCam.fov && fovCam.fov > 0) ? fovCam.fov : 65;
    if (Math.abs((ovCam.fov || 0) - targetFov) > 1e-4 || Math.abs((ovCam.aspect || 0) - aspect) > 1e-4) {
      ovCam.fov = targetFov;
      ovCam.aspect = aspect;
      ovCam.updateProjectionMatrix();
    }
  }

  if (mesh.userData && mesh.userData.is2DOverlay) {
    mesh.position.set(0, 0, -1.0);
    mesh.rotation.set(0, 0, 0);
    mesh.scale.set(2 * reqHalfSlopeX * 1.02, 2 * reqHalfSlopeY * 1.02, 1.0);
  } else {
    const bounds = computeOverlayLocalBounds(mesh);
    const posZ = bounds.isPreOffset ? 0.0 : (-1.0 - bounds.maxZ);
    const scaleZ = 1.0;
    const depthEdgeX = Math.max(0.25, -(posZ + bounds.minEdgeZX * scaleZ));
    const depthEdgeY = Math.max(0.25, -(posZ + bounds.minEdgeZY * scaleZ));
    const overscan = 1.02;
    const scaleX = ((reqHalfSlopeX * depthEdgeX) / bounds.halfW) * overscan;
    const scaleY = ((reqHalfSlopeY * depthEdgeY) / bounds.halfH) * overscan;

    mesh.position.set(-bounds.centerX * scaleX, -bounds.centerY * scaleY, posZ);
    mesh.rotation.set(0, 0, 0);
    mesh.scale.set(scaleX, scaleY, scaleZ);
  }

  mesh.updateMatrixWorld(true);
  mesh.userData = mesh.userData || {};
  mesh.userData._lastFitSig = [
    (fovCam.fov || 0).toFixed(3),
    aspect.toFixed(4),
    pm ? pm[0].toFixed(4) : '',
    pm ? pm[5].toFixed(4) : '',
    pm ? pm[8].toFixed(4) : '',
    pm ? pm[9].toFixed(4) : '',
    isXrPresenting ? 'xr' : '2d'
  ].join('|');
}

export const fitCockpitOverlayToCamera = fitCockpitCracksToCamera;
export const setupCockpitOverlayHierarchy = setupCockpitCracksHierarchy;

export function triggerCockpitCracksHit(weapon = null, durationMs = 280, damageContext = null) {
  const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
  if (weapon && typeof weapon === 'object') {
    const lastEval = weapon._decalEvaluatedAt || weapon._decalTriggeredAt || 0;
    if (lastEval && (now - lastEval) < 50) return false;
    weapon._decalEvaluatedAt = now;
    weapon._decalTriggeredAt = now;
    weapon._decalTriggered = true;
  }
  let weaponType = 'laser';
  if (typeof weapon === 'string') {
    const s = weapon.toLowerCase();
    if (/missile|strike|torpedo|rocket|warhead|ordnance|bomb/i.test(s)) {
      weaponType = 'missile';
    }
  } else if (weapon && typeof weapon === 'object') {
    const s = [
      weapon.type,
      weapon.weaponType,
      weapon.weapon_type,
      weapon.weaponName,
      weapon.weapon_name,
      weapon.name,
      weapon.id,
      weapon.weaponId,
      weapon.model_url
    ].filter(Boolean).join(' ').toLowerCase();
    if (/missile|strike|torpedo|rocket|warhead|ordnance|bomb/i.test(s)) {
      weaponType = 'missile';
    }
  }

  const overlay = getActiveOverlay();
  const evalResult = evaluateWeaponDecalThreshold(overlay, damageContext);
  if (evalResult.shouldTrigger) {
    if (overlay) {
      toggleRandomWeaponDecal(overlay, weaponType);
    } else if (activeCockpitCracksPool && typeof activeCockpitCracksPool.triggerWeaponDecal === 'function') {
      activeCockpitCracksPool.triggerWeaponDecal(weaponType);
    }
  }

  if (typeof document !== 'undefined') {
    const redEdges = document.getElementById('cockpit-edges-red');
    if (redEdges) {
      redEdges.style.opacity = '1.0';
      setTimeout(() => {
        redEdges.style.opacity = '0';
      }, durationMs);
    }
  }
  return evalResult.shouldTrigger;
}

export function triggerShieldDepletedCockpitCracks(visible = true) {
  const overlay = getActiveOverlay();
  if (overlay) {
    toggleBrokenCoreDecal(overlay, visible);
  } else if (activeCockpitCracksPool && typeof activeCockpitCracksPool.triggerShieldDepletedDecal === 'function') {
    activeCockpitCracksPool.triggerShieldDepletedDecal(visible);
  }
}

export function triggerGameOverCockpitCracks(durationMs = 4000) {
  const overlay = getActiveOverlay();
  if (overlay) {
    toggleGameOverDecals(overlay, durationMs);
  } else if (activeCockpitCracksPool && typeof activeCockpitCracksPool.showGameOverCockpitCracks === 'function') {
    activeCockpitCracksPool.showGameOverCockpitCracks(durationMs);
  }
  if (typeof document !== 'undefined') {
    const redEdges = document.getElementById('cockpit-edges-red');
    if (redEdges) {
      redEdges.style.opacity = '1.0';
    }
  }
}

export function hideCockpitCracks() {
  const overlay = getActiveOverlay();
  if (overlay) {
    resetCockpitOverlayDecals(overlay);
  } else if (activeCockpitCracksPool && typeof activeCockpitCracksPool.hideCockpitCracks === 'function') {
    activeCockpitCracksPool.hideCockpitCracks();
  }
  resetCockpitDecalThreshold(overlay);
  if (typeof document !== 'undefined') {
    const redEdges = document.getElementById('cockpit-edges-red');
    if (redEdges) {
      redEdges.style.opacity = '0';
    }
  }
}

export function getActiveCockpitCracksOverlay() {
  return getActiveOverlay();
}

export function handleStageEvent(eventName, payload, engineApi) {
  console.log(`[Stage 3: Singularity Core] Event received: ${eventName}`, payload);
  if (eventName === 'Core Collapse Breakthrough') {
    if (engineApi && typeof engineApi.showToast === 'function') {
      engineApi.showToast('🏆 STAGE 3 OBJECTIVE COMPLETE: Core Collapse Breakthrough');
    }
  }
}

export function applyStage(engineApi) {
  if (!engineApi) return stageConfig;
  console.log(`[Stage 3: Singularity Core] Applying Mobile Profile configuration...`);

  if (typeof engineApi.setThemeColors === 'function') {
    engineApi.setThemeColors(stageConfig.visual);
  }
  if (typeof engineApi.setHudStatus === 'function') {
    engineApi.setHudStatus('STAGE 3: SINGULARITY CORE [MOBILE]');
  }
  if (typeof engineApi.setFlightConfig === 'function') {
    engineApi.setFlightConfig(stageConfig.visual.flight);
  }
  if (typeof engineApi.setWeapons === 'function') {
    engineApi.setWeapons(stageConfig.weapons);
  }
  if (typeof engineApi.setEnemies === 'function') {
    engineApi.setEnemies(stageConfig.enemies);
  }
  if (typeof engineApi.setStageObjectives === 'function') {
    engineApi.setStageObjectives(stageConfig.objectives || []);
  }
  if (typeof engineApi.setDeviceControls === 'function') {
    engineApi.setDeviceControls(stageConfig.controls);
  }
  if (typeof engineApi.setEnemyMovementHandler === 'function') {
    engineApi.setEnemyMovementHandler(updateEnemyMovement);
  }
  if (typeof engineApi.setEnemyWeaponHandler === 'function') {
    engineApi.setEnemyWeaponHandler(fireEnemyWeapon);
  }
  if (typeof engineApi.setStageWaveHandler === 'function') {
    engineApi.setStageWaveHandler(updateStageWaves);
  }
  if (typeof engineApi.showToast === 'function') {
    engineApi.showToast('🚀 STAGE 3: SINGULARITY CORE [MOBILE] LOADED');
  }


    // --- Mount Cockpit Overlay Across Cockpit Window via Pool ---
  const camera = (engineApi && engineApi.camera) || (typeof window !== 'undefined' && window.camera);
  const scene = (engineApi && engineApi.scene) || (typeof window !== 'undefined' && window.scene);
  const pool = (engineApi && typeof engineApi.getObjectPool === 'function' ? engineApi.getObjectPool() : null)
    || (typeof window !== 'undefined' && window.stageObjectPool)
    || null;

  setupCockpitCracksOverlay(camera, pool, scene);

  // Resize and orientation handlers to maintain perfect cockpit fit dynamically scaling overlay with FOV
  if (typeof window !== 'undefined') {
    if (!window._cockpitCracksResizeBound) {
      const onResizeFit = () => {
        const inXr = !!(window.renderer && window.renderer.xr && window.renderer.xr.isPresenting);
        let cam = window.camera;
        if (inXr && window.renderer.xr && typeof window.renderer.xr.getCamera === 'function') {
          const xrCam = window.renderer.xr.getCamera();
          if (xrCam && Array.isArray(xrCam.cameras) && xrCam.cameras.length > 0) {
            cam = xrCam.cameras[0];
          } else if (xrCam) {
            cam = xrCam;
          }
        }
        const ov = (typeof window.getActiveCockpitCracksOverlay === 'function' ? window.getActiveCockpitCracksOverlay() : null) || getActiveOverlay();
        if (ov && cam && typeof window.fitCockpitCracksToCamera === 'function') {
          window.fitCockpitCracksToCamera(ov, cam);
        }
      };
      window.addEventListener('resize', onResizeFit);
      window.addEventListener('orientationchange', () => setTimeout(onResizeFit, 200));
      window._cockpitCracksResizeBound = true;
    }

    // Hook enemy hit detection:
    if (typeof window.applyDamageToPlayer === 'function') {
      const baseDamage = window.applyDamageToPlayer._baseApplyDamage || window.applyDamageToPlayer;
      const wrappedApplyDamage = function(dmg, ...args) {
        const weapon = args[0] || (typeof dmg === 'object' ? dmg : null);
        const st = (typeof window.state !== 'undefined' && window.state) ? window.state : null;
        const maxShield = (st && st.maxShield > 0) ? st.maxShield : 100;
        const maxHealth = (st && st.maxHealth > 0) ? st.maxHealth : 100;
        const shieldBefore = st && typeof st.playerShield === 'number' ? st.playerShield : maxShield;
        const healthBefore = st && typeof st.playerHealth === 'number' ? st.playerHealth : maxHealth;

        wrappedApplyDamage._inStageWrapper = true;
        let ret;
        try {
          ret = baseDamage.apply(this, [dmg, ...args]);
        } finally {
          wrappedApplyDamage._inStageWrapper = false;
        }

        const shieldAfter = st && typeof st.playerShield === 'number' ? st.playerShield : 0;
        const healthAfter = st && typeof st.playerHealth === 'number' ? st.playerHealth : maxHealth;

        // Only turn on a weapon decal when shield or health (whichever is being reduced)
        // drops by 100% / availableDecals (e.g., 100 / 18 = 5.55% per decal)
        triggerCockpitCracksHit(weapon, 280, {
          shieldBefore,
          shieldAfter,
          healthBefore,
          healthAfter,
          maxShield,
          maxHealth
        });

        // When shield reaches 0%, BrokenSpiderWeb Core decal remains on unless shield % increases back above 0%
        if (shieldAfter <= 0 || healthAfter <= 0) {
          triggerShieldDepletedCockpitCracks(true);
        } else if (shieldAfter > 0 && healthAfter > 0) {
          triggerShieldDepletedCockpitCracks(false);
        }

        // When health reaches 0%, both BrokenSpiderWeb Core and BrokenSpiderWeb Screen decals turn on for 4 seconds
        if (healthAfter <= 0) {
          triggerGameOverCockpitCracks(4000);
        }

        return ret;
      };
      wrappedApplyDamage._cockpitCracksHooked = true;
      wrappedApplyDamage._baseApplyDamage = baseDamage;
      wrappedApplyDamage._inStageWrapper = false;
      window.applyDamageToPlayer = wrappedApplyDamage;
    }

    if (!window._cockpitCracksEventsBound) {
      window.addEventListener('cockpitHit', (e) => window.triggerCockpitCracksHit && window.triggerCockpitCracksHit(e.detail));
      window.addEventListener('playerDamage', (e) => window.triggerCockpitCracksHit && window.triggerCockpitCracksHit(e.detail));
      window.addEventListener('cockpitImpact', (e) => window.triggerCockpitCracksHit && window.triggerCockpitCracksHit(e.detail));
      window.addEventListener('shieldDepleted', () => window.triggerShieldDepletedCockpitCracks && window.triggerShieldDepletedCockpitCracks());
      window.addEventListener('gameOverCracks', () => window.triggerGameOverCockpitCracks && window.triggerGameOverCockpitCracks(4000));
      window._cockpitCracksEventsBound = true;
    }

    const baseCustomFx = (window.executeCustomWeaponImpactFx && window.executeCustomWeaponImpactFx._baseCustomFx) || window.executeCustomWeaponImpactFx;
    const wrappedCustomFx = function(bolt, normX, normY, canvas) {
      if (typeof baseCustomFx === 'function') {
        try { baseCustomFx(bolt, normX, normY, canvas); } catch (e) {}
      }
      triggerCockpitCracksHit(bolt);
    };
    wrappedCustomFx._baseCustomFx = baseCustomFx;
    window.executeCustomWeaponImpactFx = wrappedCustomFx;

    window.triggerCockpitCracksHit = triggerCockpitCracksHit;
    window.triggerCockpitOverlayHit = triggerCockpitCracksHit;
    window.flashCockpitCracks = triggerCockpitCracksHit;
    window.triggerShieldDepletedCockpitCracks = triggerShieldDepletedCockpitCracks;
    window.triggerGameOverCockpitCracks = triggerGameOverCockpitCracks;
    window.hideCockpitCracks = hideCockpitCracks;
    window.resetCockpitOverlayDecals = resetCockpitOverlayDecals;
    window.setupCockpitCracksOverlay = setupCockpitCracksOverlay;
    window.setupCockpitOverlayHierarchy = setupCockpitCracksHierarchy;
    window.fitCockpitCracksToCamera = fitCockpitCracksToCamera;
    window.fitCockpitOverlayToCamera = fitCockpitCracksToCamera;
    window.getActiveCockpitCracksOverlay = getActiveCockpitCracksOverlay;
    window.getAvailableCockpitDecalCount = getAvailableCockpitDecalCount;
    window.resetCockpitDecalThreshold = resetCockpitDecalThreshold;
    window.syncCockpitDecalThreshold = syncCockpitDecalThreshold;
    window.evaluateWeaponDecalThreshold = evaluateWeaponDecalThreshold;
  }

  return stageConfig;
}

export default {
  stageConfig,
  applyStage,
  fireEnemyWeapon,
  updateEnemyMovement,
  updateStageWaves,
  handleStageEvent,
  stageEvents,
  setupCockpitCracksOverlay,
  setupCockpitOverlayHierarchy,
  triggerCockpitCracksHit,
  triggerShieldDepletedCockpitCracks,
  triggerGameOverCockpitCracks,
  hideCockpitCracks,
  fitCockpitCracksToCamera,
  fitCockpitOverlayToCamera,
  getActiveCockpitCracksOverlay,
  getAvailableCockpitDecalCount,
  resetCockpitDecalThreshold,
  syncCockpitDecalThreshold,
  evaluateWeaponDecalThreshold
};